import os # Bound this frozen-model verification to one numerical CPU thread.
os.environ['OMP_NUM_THREADS']='1';os.environ['OPENBLAS_NUM_THREADS']='1' # Avoid competing with native qualification runs through nested threading.
import argparse,json,time # Preserve explicit verification scope, frozen identities and actual inference timing.
import numpy as np # Retain native full fields and complete prediction errors on the unseen mesh.
import complex_operator as base # Use the unchanged complete-entity graph and physical-group error definitions.
from complex_operator_finalize import load # Reconstruct the explicitly saved next-state architecture in a fresh process.
def run(family): # Verify an existing finer native mesh only after the ordinary final evaluation is complete.
    assert family=='friction','Only the explicitly requested existing friction refinements are registered';registry=json.loads((base.ROOT/'learning/campaign_learning_index.json').read_text());directory=base.ROOT/registry['families'][family];assert (directory/'summary.json').exists(),'Final frozen test evaluation must precede this separate mesh-transfer check';frozen=json.loads((directory/'frozen_models_before_test.json').read_text());records=[];started=time.monotonic() # Do not change model choice or contaminate the independent test denominator.
    for strategy,item in frozen.items(): # Compare the same already frozen initial, active and random predictors.
        assert base.digest(base.resolve_path(item['checkpoint']))==item['sha256'],'Frozen checkpoint changed';model,norm=load(item['checkpoint']) # Refuse to evaluate a subsequently changed learned model.
        for number in [0,1]: # Use only the two existing native refinement histories specifically authorized for verification.
            name=f'friction_verify_{number}_mesh';row=json.loads((base.ROOT/'friction/cases'/name/'case.json').read_text());case=base.read_case(row,True);assert case['nodes']>697,'Requested reference is not the registered finer graph';case_started=time.monotonic();prediction=base.rollout(model,case,norm);result=base.field_metrics(prediction,case,norm);result.update({'strategy':strategy,'checkpoint_sha256':item['sha256'],'reference_sha256':case['npz_sha256'],'seconds':time.monotonic()-case_started,'native_graph_entities':case['nodes'],'training_graph_entities':697,'split':'mesh_transfer_verification','independent_loading_history':False}) # Evaluate every native node and integration point from the known initial state only.
            output=directory/'mesh_transfer'/strategy;output.mkdir(parents=True,exist_ok=True);np.savez_compressed(output/f'{name}.npz',prediction=prediction,reference=case['reference'],difference=prediction-case['reference'],state_mask=case['state_mask'],xyz=case['xyz'],fields=np.asarray(case['fields']),npz_sha256=np.asarray(case['npz_sha256']));base.write(output/f'{name}.json',result);records.append(result);print(json.dumps({'strategy':strategy,'id':name,'entities':case['nodes'],'accuracy_pass':result['accuracy_pass'],'mean_physical_group_relative_L2':result['mean_physical_group_relative_L2'],'seconds':result['seconds']}),flush=True) # Preserve complete fine-mesh errors without retraining or a response projection.
    summary={'scope':'Existing finer native meshes; physical parameters can coincide with training histories, but these graph discretizations were not fitted. This is a development mesh-transfer verification, outside the four test and four OOD history denominators.','new_native_solves':0,'parameter_updates':0,'model_reselection':False,'all_native_entities_retained':True,'cold_rollout_from_initial_only':True,'records':records,'seconds':time.monotonic()-started,'engineering_release':'HOLD'};base.write(directory/'mesh_transfer/summary.json',summary) # Keep numerical graph-size support distinct from successful unseen-mesh accuracy.
if __name__=='__main__': # Run only the already registered verification family.
    parser=argparse.ArgumentParser();parser.add_argument('--family',choices=['friction'],required=True);run(parser.parse_args().family) # Do not silently add new expensive solves or tuning stages.
